146	        rejectMissingOrBlankFields(ownerFieldsDto);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        applyAddress(owner);
150	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
151	        owner.setEmail(normalizeEmail(owner.getEmail()));
