67	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
68	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
69	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
70	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
71	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
72	    public abstract OwnerDto toOwnerDto(Owner owner);
73	
74	    public abstract Owner toOwner(OwnerDto ownerDto);
75	
76	    @Mapping(target = "id", ignore = true)
77	    @Mapping(target = "pets", ignore = true)
78	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
79	
80	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
81	
82	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
83	
84	    /**
85	     * Computes an owner's membership points. Points start at 0 and accumulate: {@value #EMAIL_POINTS} when an
86	     * email is present, {@value #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
87	     * {@value #LARGE_HOUSEHOLD_POINTS} for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, and
88	     * {@value #TENURE_POINTS} for a tenure of at least {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal
89	     * year(s) (measured from {@code registrationDate}). Because a newly created owner has zero elapsed fiscal
90	     * years, a new owner never earns the tenure points.
91	     *
92	     * @param owner the owner whose points are being computed
93	     * @return the owner's membership points (0 or more)
94	     */
95	    protected Integer membershipPoints(Owner owner) {
96	        int points = 0;
97	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
98	            points += EMAIL_POINTS;
99	        }
100	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
101	            points += NO_NAMESAKE_POINTS;
102	        }
103	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_SIZE) {
104	            points += LARGE_HOUSEHOLD_POINTS;
105	        }
106	        if (tenureFiscalYears(owner) >= TENURE_POINTS_FISCAL_YEARS) {
107	            points += TENURE_POINTS;
108	        }
109	        return points;
110	    }
111	
112	    /**
113	     * Maps an owner's membership points to a numeric membership level: level 1 for 0-1 points, level 2 for
114	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
115	     *
116	     * @param owner the owner whose level is being computed
117	     * @return the membership level (between 1 and 4 inclusive)
118	     */
119	    protected Integer membershipLevel(Owner owner) {
120	        int points = membershipPoints(owner);
121	        if (points >= 6) {
122	            return 4;
123	        }
124	        if (points >= 4) {
125	            return 3;
126	        }
127	        if (points >= 2) {
128	            return 2;
129	        }
130	        return 1;
131	    }
132	
133	    /**
134	     * Computes an owner's tenure as the number of elapsed fiscal years between {@code registrationDate} and
135	     * today: the difference between the fiscal year (starting 1 July) of today and that of the registration
136	     * date. A newly created owner (registered in the current fiscal year) has zero tenure. Owners with no
137	     * {@code registrationDate}, or a registration date in a later fiscal year, are treated as zero tenure.
138	     *
139	     * @param owner the owner whose tenure is being computed
140	     * @return the owner's tenure in elapsed fiscal years, never negative
141	     */
142	    protected long tenureFiscalYears(Owner owner) {
143	        LocalDate registrationDate = owner.getRegistrationDate();
144	        if (registrationDate == null) {
145	            return 0;
146	        }
147	        long years = (long) fiscalYearStart(LocalDate.now()) - fiscalYearStart(registrationDate);
148	        return Math.max(years, 0);
149	    }
150	
151	    /**
152	     * Derives an owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, from the (already
153	     * business-day-adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is labelled by
154	     * the calendar year in which it starts, so a registration on or after 1 July belongs to that year's
155	     * fiscal year and an earlier one to the previous year's (e.g. {@code 2026-08-15} yields {@code 'FY26'}).
156	     *
157	     * @param owner the owner whose fiscal year is being derived
158	     * @return the owner's fiscal year as {@code 'FY<YY>'}
159	     */
160	    protected String fiscalYear(Owner owner) {
161	        return "FY" + fiscalYearSuffix(owner.getRegistrationDate());
162	    }
163	
164	    /**
165	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
166	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the shared segment
167	     * used by both {@link #fiscalYear(Owner)} and the membership number.
168	     *
169	     * @param date the date whose fiscal-year suffix is computed
170	     * @return the zero-padded two-digit fiscal-year suffix
171	     */
172	    protected String fiscalYearSuffix(LocalDate date) {
173	        return String.format("%02d", fiscalYearStart(date) % 100);
174	    }
175	
176	    /**
177	     * Returns the calendar year in which the fiscal year containing {@code date} starts. The fiscal year
178	     * starts on 1 July, so dates from July onward start their fiscal year in the same calendar year, while
179	     * dates from January to June belong to the fiscal year that started in the previous calendar year.
180	     *
181	     * @param date the date whose fiscal-year start is computed
182	     * @return the calendar year in which the containing fiscal year starts
183	     */
184	    protected int fiscalYearStart(LocalDate date) {
185	        int year = date.getYear();
186	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year : year - 1;
187	    }
188	
189	    /**
190	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits contained in
191	     * the owner's {@code customerCode}. Non-digit characters (such as the letters and dashes in the code) are
192	     * skipped; the rightmost digit is doubled and every second digit thereafter, digits exceeding 9 after
193	     * doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
194	     *
195	     * @param owner the owner whose check digit is being computed
196	     * @return the Luhn check digit (between 0 and 9 inclusive) over the customer code's digits
197	     */
198	    protected Integer checkDigit(Owner owner) {
199	        String code = owner.getCustomerCode() == null ? "" : owner.getCustomerCode();
200	        int sum = 0;
201	        boolean dbl = true;
202	        for (int i = code.length() - 1; i >= 0; i--) {
203	            char c = code.charAt(i);
204	            if (c < '0' || c > '9') {
205	                continue;
206	            }
207	            int d = c - '0';
208	            if (dbl) {
209	                d *= 2;
210	                if (d > 9) {
211	                    d -= 9;
212	                }
213	            }
214	            sum += d;
215	            dbl = !dbl;
216	        }
217	        return (10 - (sum % 10)) % 10;
218	    }
219	
220	    /**
221	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
222	     * present, otherwise {@code 'PHONE'}.
223	     *
224	     * @param owner the owner whose contact preference is being computed
225	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
226	     */
227	    protected String contactPreference(Owner owner) {
228	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
229	    }
230	
231	    /**
232	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
233	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
234	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
235	     * {@code birthDate}, so the field is simply absent for owners created without one.
236	     *
237	     * @param owner the owner whose age band is being derived
238	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
239	     */
240	    protected String ageBand(Owner owner) {
241	        if (owner.getBirthDate() == null) {
242	            return null;
243	        }
244	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
245	        int years = Period.between(owner.getBirthDate(), reference).getYears();
246	        if (years < 18) {
247	            return "MINOR";
248	        }
249	        if (years < 65) {
250	            return "ADULT";
251	        }
252	        return "SENIOR";
253	    }
254	
255	    /**
256	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
257	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
258	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'}). This is the single key used for duplicate detection,
259	     * so the value returned here matches the one the create endpoint compares.
260	     *
261	     * @param owner the owner whose identity key is being derived
262	     * @return the owner's identity key
263	     */
264	    protected String identityKey(Owner owner) {
265	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
266	        String email = owner.getEmail() == null ? "" : owner.getEmail();
267	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
268	        return telephone + "|" + email + "|" + householdId;
269	    }
270	
271	    /**
272	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
273	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
274	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
275	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
276	     * <p>
277	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
278	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
279	     *
280	     * @param owner the owner whose telephone is being formatted
281	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
282	     */
283	    protected String telephoneDisplay(Owner owner) {
284	        String telephone = owner.getTelephone();
285	        if (telephone == null || !telephone.startsWith("+")) {
286	            return telephone;
287	        }
288	        String digits = telephone.substring(1);
289	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
290	        if (digits.length() <= countryCodeLength) {
291	            return telephone;
292	        }
293	        String countryCode = digits.substring(0, countryCodeLength);
294	        String national = digits.substring(countryCodeLength);
295	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
296	        for (int i = 0; i < national.length(); i++) {
297	            if (i % 3 == 0) {
298	                grouped.append(' ');
299	            }
300	            grouped.append(national.charAt(i));
301	        }
302	        return grouped.toString();
303	    }
304	
305	    /**
306	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
307	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
308	     * title was given.
309	     *
310	     * @param owner the owner whose salutation is being composed
311	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
312	     */
313	    protected String salutation(Owner owner) {
314	        String title = owner.getTitle();
315	        if (title == null || title.isBlank()) {
316	            return owner.getLastName();
317	        }
318	        return title + " " + owner.getLastName();
319	    }
320	
321	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
322	        OwnerPageDto ownerPageDto = new OwnerPageDto();
323	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
324	        ownerPageDto.setPage(ownerPage.getNumber());
325	        ownerPageDto.setSize(ownerPage.getSize());
326	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
327	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
328	        return ownerPageDto;
329	    }
330	}
